use implementation::*;
#[derive(Clone)] struct Tree(Vec<Vec<usize>>);
impl FiniteTree for Tree { fn node_count(&self)->usize {self.0.len()} fn children(&self,n:usize)->&[usize] {&self.0[n]} }
struct Fast(Vec<f64>); impl FastOracle for Fast {fn evaluate(&mut self,n:usize)->Result<f64,String>{Ok(self.0[n])}}
struct Slow{ values:Vec<f64>, rng:u64, sigma:f64,bias:f64 }
impl SlowOracle for Slow{fn sample(&mut self,n:usize)->Result<f64,String>{Ok(self.values[n]+self.bias+if next(&mut self.rng)&1==0 {-self.sigma}else{self.sigma})}}
fn next(s:&mut u64)->u64{*s=s.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);*s^(*s>>29)}
fn extend(t:&mut Tree,v:usize,d:usize,limit:usize,r:&mut u64){if d==limit{return} let b=if d==0 {2+(next(r)%2)}else {1+(next(r)%3)};for _ in 0..b {let u=t.0.len();t.0.push(vec![]);t.0[v].push(u);extend(t,u,d+1,limit,r)}}
fn exact(t:&Tree,v:usize,d:usize,r:&mut u64,vals:&mut[f64],depths:&mut[usize])->f64{depths[v]=d;let x=if t.children(v).is_empty(){(next(r)%4001)as f64/1000.-2.}else {t.children(v).iter().map(|&u|exact(t,u,d+1,r,vals,depths)).fold(if d%2==0 {f64::NEG_INFINITY}else {f64::INFINITY},if d%2==0 {f64::max}else {f64::min})};vals[v]=x;x}
fn wide_samples(){let mut sampled=0;for seed in 0..24{let mut t=Tree(vec![vec![]]);let mut depths=vec![0];let mut means=vec![0.6];let mut cursor=0;while cursor<t.node_count(){if depths[cursor]<3 {for _ in 0..if cursor==0 {3}else {16}{let u=t.node_count();t.0.push(vec![]);t.0[cursor].push(u);depths.push(depths[cursor]+1);means.push(if cursor==0 {0.4+0.1*(u-1)as f64}else {means[cursor]});}}cursor+=1;}let n=t.node_count();let mut c=TwoFidelity::new(t,Fast(means.clone()),Slow{values:means.clone(),rng:seed+31,sigma:0.003,bias:0.0},Config{slow_cost:2.5,trace:true,max_cost:10000.,..Config::default()},OracleContract{envelope:vec![0.,0.5,1.,1.5],sigma:0.003,slow_bias_bound:0.,provenance:"independent wide depth3 minimax with bounded symmetric noise".into(),justified:true}).unwrap();let r=c.run().unwrap();assert_eq!(r.stop,StopReason::Separated);assert!(means[r.recommendation.unwrap()]>=0.6-1e-12);assert!(r.profile.slow_queries>0);assert_eq!(r.total_cost,r.profile.fast_queries as f64+2.5*r.profile.slow_queries as f64);for v in 0..n{if let Some(i)=c.interval(v){assert!(i.lower<=means[v]+1e-12 && means[v]<=i.upper+1e-12);}}sampled+=r.profile.slow_queries;}println!("{{\"wide_cases\":24,\"slow_samples\":{sampled},\"passed\":true}}");}
fn main(){wide_samples();let mut count=0;let mut states=0;let mut expansion=0;let mut samples=0;for depth in 1..=4{for seed in 0..48{let mut rng=31+seed*17;let mut tree=Tree(vec![vec![]]);extend(&mut tree,0,0,depth,&mut rng);let n=tree.node_count();let mut values=vec![0.;n];let mut depths=vec![0;n];exact(&tree,0,0,&mut rng,&mut values,&mut depths);
// Reverse non-root IDs and child order, defeating heap-index/depth assumptions.
let id=|v|if v==0 {0}else {n-v};let mut shuffled=Tree(vec![vec![];n]);let mut sv=vec![0.;n];let mut sd=vec![0;n];for v in 0..n{shuffled.0[id(v)]=tree.children(v).iter().rev().map(|&u|id(u)).collect();sv[id(v)]=values[v];sd[id(v)]=depths[v];}
for mode in 0..3{let eps=if mode==1 {0.1}else {0.};let bias=if mode==2 {0.01}else {0.};let fast:Vec<_>=(0..n).map(|v|sv[v]+((next(&mut rng)%2001)as f64/1000.-1.)*0.5*(depth-sd[v])as f64).collect();let mut c=TwoFidelity::new(shuffled.clone(),Fast(fast),Slow{values:sv.clone(),rng:seed+91,sigma:0.005,bias},Config{slow_cost:2.5,epsilon:eps,trace:true,max_cost:100000.,..Config::default()},OracleContract{envelope:(0..=depth).map(|h|0.5*h as f64).collect(),sigma:0.005,slow_bias_bound:bias,provenance:"independent irregular balanced fixture; exact values, bounded bias/noise, reversed IDs".into(),justified:true}).unwrap();let r=c.run().unwrap();assert_eq!(r.stop,StopReason::Separated,"d{depth}seed{seed}mode{mode}");assert!(sv[0]-sv[r.recommendation.unwrap()]<=eps+1e-12);assert_eq!(r.total_cost,r.profile.fast_queries as f64+2.5*r.profile.slow_queries as f64);assert!(r.total_cost<=100000.);assert_eq!(r.profile.rounds as usize,r.trace.len());for v in 0..n {if let Some(i)=c.interval(v){assert!(i.lower<=sv[v]+1e-12 && sv[v]<=i.upper+1e-12);states+=1;}} expansion+=r.profile.expansions;samples+=r.profile.slow_queries;assert!(c.run().is_err());count+=1;}}}println!("{{\"cases\":{count},\"checked_exposed_intervals\":{states},\"expansions\":{expansion},\"slow_samples\":{samples},\"passed\":true}}");}
